def load(f,dec=5):
    d=pd.read_csv(f).iloc[::dec]
    return {k:d[c].values for k,c in [('t','time_s'),('P','active_power_pu'),('Q','reactive_power_pu'),('V','voltage_pu'),('th','bus_angle_rad'),('Vs','voltage_setpoint_pu')]}
files=['train/A_vref_op1.csv','train/A_amb_op1.csv','train/A_load_op2.csv','train/A_gentrip_op1.csv','train/A_vref_op3.csv','train/A_line_op3.csv','train/A_fault_op1.csv']
D={f:load(f) for f in files}
def simQ(p,d):
    Ki,Tl,Kp,Tm=p
    t,V,Vs=d['t'],d['V'],d['Vs']; n=len(t); dt=t[1]-t[0]; Q0=d['Q'][0]
    am=np.exp(-dt/Tm); a=np.exp(-dt/Tl)
    Vf=V[0]; x=0.0; Qo=np.empty(n)
    for k in range(n):
        e=Vs[k]-Vf
        Qo[k]=Q0+Kp*(Vs[k]-V[k])+x
        x=a*x+(1-a)*Ki*Tl*e
        Vf=am*Vf+(1-am)*V[k]
    return Qo
def res(p):
    return np.concatenate([(simQ(p,d)-d['Q'])[20:] for d in D.values()])
t0=time.time(); print(np.sqrt(np.mean(res([10,1,0,0.01])**2)), time.time()-t0)
best=None
for p0 in [[10,1,0,0.01],[20,0.5,5,0.01],[5,3,2,0.1]]:
    sol=least_squares(res,p0,bounds=([0,0.01,-50,0.001],[500,100,50,2]),x_scale='jac',max_nfev=100)
