sol=least_squares(res,p0,args=(allf,),max_nfev=30)
A,B,C,Dm=mats(sol.x)
print('all rmse',np.sqrt(np.mean(sol.fun**2)).round(5),'eig',np.linalg.eigvals(A).round(3),'static',(C@(-np.linalg.solve(A,B))+Dm).round(3))
for f in D: print('  ',f,np.sqrt(np.mean((simQ(sol.x,D[f])-D[f]['Q'])[5:]**2)).round(4))
np.save('qfinal_all.npy',sol.x)
print(sol.x.tolist())
